<script setup>
import { Link,router } from '@inertiajs/vue3';
import { reactive } from 'vue';
import AssessmentLayout from './AssessmentLayout.vue';
import { confirmAction } from './confirmAction.js';
const props=defineProps({item:Object,transactions:Object,stats:Object,filters:Object});
const filter=reactive({search:props.filters?.search||'',type:props.filters?.type||''});
const cancelTransaction=async tx=>{if(await confirmAction('Batalkan transaksi ini?', 'Batalkan transaksi')) router.post(route('admin.shop-items.transactions.cancel',[props.item.id,tx.id]));};
</script>
<template><AssessmentLayout :title="item.name" subtitle="Detail item dan riwayat transaksi." breadcrumb="Komunitas & pengguna"><template #action><Link class="secondary" :href="route('redesign.shop-items.edit',item.id)">Edit item</Link></template><div class="panel" style="margin-bottom:20px"><div class="fields"><div><span class="muted">Harga</span><h2>{{ item.price_gold }} gold</h2></div><div><span class="muted">Jumlah dibeli</span><h2>{{ stats.purchase_qty }}</h2></div><div><span class="muted">Gold masuk</span><h2>{{ stats.purchase_gold }}</h2></div><div><span class="muted">Pemilik aktif</span><h2>{{ stats.active_holder_count }}</h2></div></div></div><section class="panel"><h2>Transaksi</h2><form class="filters" @submit.prevent="router.get(route('redesign.shop-items.detail',item.id),filter)"><input v-model="filter.search" placeholder="Cari pengguna atau catatan" /><select v-model="filter.type"><option value="">Semua jenis</option><option value="purchase">Pembelian</option><option value="consume_unlock">Penggunaan</option></select><button class="secondary">Terapkan</button></form><div class="table-wrap"><table><thead><tr><th>Waktu</th><th>Pengguna</th><th>Jenis</th><th>Jumlah</th><th>Gold</th><th>Status</th><th>Aksi</th></tr></thead><tbody><tr v-for="tx in transactions.data" :key="tx.id"><td>{{ tx.created_at }}</td><td>{{ tx.user?.name||'—' }}</td><td>{{ tx.type }}</td><td>{{ tx.quantity }}</td><td>{{ tx.gold_change }}</td><td>{{ tx.is_cancelled?'Dibatalkan':'Selesai' }}</td><td><button v-if="tx.type==='purchase'&&!tx.is_cancelled" type="button" class="secondary" @click="cancelTransaction(tx)">Batalkan</button></td></tr><tr v-if="!transactions.data?.length"><td colspan="7">Belum ada transaksi.</td></tr></tbody></table></div><div class="pager"><Link v-for="(link,index) in transactions.links" :key="index" :href="link.url||'#'" :class="{active:link.active,disabled:!link.url}" v-html="link.label" /></div></section></AssessmentLayout></template>
